import { onCLS, onINP, onLCP, onTTFB, onFCP } from 'web-vitals/attribution';

function sendToBackend(metric: { text: string; value: number; attribution: unknown }) {
  // Use beacon para garantir envio mesmo no unload
  navigator.sendBeacon('/rum', JSON.stringify({
    name: metric.name,
    value: metric.value,
    url: location.pathname,
    conn: (navigator as any).connection?.effectiveType,
    device: innerWidth > 900 ? 'desktop' : 'mobile',
    // attribution traz qual elemento causou (LCP element, long task source)
    attribution: metric.attribution,
  }));
}

onLCP(sendToBackend);
onINP(sendToBackend);
onCLS(sendToBackend);
onTTFB(sendToBackend);
onFCP(sendToBackend);
